{"code": "// Step 1: present for missing.txt — must fail, catch the error, don't create the file
try {
  await tools.present({ files: [{ path: "missing.txt", description: "must not exist" }] });
  console.log("UNEXPECTED: present succeeded for missing.txt");
} catch (err) {
  console.log("Caught present error for missing.txt:", typeof err, String(err).slice(0, 200));
}

// Step 2: run the exact bash command to create the two report files
const res = await tools.bash({
  command: 'printf "DELIVERED_REPORT\n" > report.txt; printf "DELIVERED_NOTE\n" > 说明.txt',
  description: "Write DELIVERED_REPORT and DELIVERED_NOTE to files",
});
console.log("bash exit:", res.exitCode);

// Step 3: present for report.txt and 说明.txt (must succeed)
const p2 = await tools.present({
  files: [
    { path: "report.txt", description: "delivered report" },
    { path: "说明.txt", description: "delivered note" },
  ],
});
console.log("present ok, files:", p2.files.map((f) => f.path).join(", "));

// Step 4: deliberately throw a plain string AFTER_PRESENT (not an Error)
throw "AFTER_PRESENT";", "description": "Present files then deliberately throw AFTER_PRESENT"}

